const QUALITY=["Poor","Common","Uncommon","Rare","Epic","Legendary","Artifact"];
const clean=value=>typeof value==="string"?value.trim().replace(/\s+/g," "):"";
export function variantDetails(item){
 const text=clean(item?.variant);
 const match=/^(\d+):(\d+):(\d+)$/.exec(text);
 if(!match||text==="0:0:0"||text==="")return {suffix:"",bonuses:[],enchant:"",unresolved:false,hasVariant:false};
 const [enchantId,rawProperty,factor]=match.slice(1).map(Number);
 const signedProperty=rawProperty>0x7fffffff?rawProperty-0x100000000:rawProperty;
 const found=signedProperty>0?PROPERTIES[signedProperty]:null;
 const bonus=found?.[1]||[];
 const enchant=enchantId?ENCHANTS[enchantId]||"":""; 
 return {suffix:found?.[0]||"",bonuses:bonus,enchant,unresolved:Boolean((signedProperty&&!found)||(enchantId&&!enchant)),hasVariant:true,
   propertyId:signedProperty,enchantId,suffixFactor:factor};
}
export function displayItemName(item){
 const id=Number(item?.item_id),base=clean(item?.item_name)||"Item #"+(Number.isSafeInteger(id)&&id>0?id:"Unknown");
 const suffix=variantDetails(item).suffix;
 return suffix && !base.toLowerCase().endsWith(suffix.toLowerCase())?base+" "+suffix:base;
}
function rarity(item){
 const quality=Number(item?.quality);
 return item?.quality!=null && Number.isInteger(quality)&&quality>=0&&quality<QUALITY.length?QUALITY[quality]:"unavailable";
}
export function variantLines(item){
 const info=variantDetails(item);
 if(!info.hasVariant)return [];
 const result=[];
 if(info.bonuses.length)result.push(...info.bonuses);
 if(info.enchant)result.push("Enchant: "+info.enchant);
 if(info.unresolved)result.push("Unmapped random enchantment – exact bonuses unavailable.");
 return result;
}
export function itemTooltip(item){
 const id=Number(item?.item_id);
 const itemId=Number.isSafeInteger(id)&&id>0?String(id):"Unknown";
 const v=variantDetails(item);
 const known=clean(item?.item_name).length>0;
 return [
   displayItemName(item),
   "Rarity: "+rarity(item),
   "Item ID: "+itemId,
   ...variantLines(item),
   ...(v.hasVariant&&v.bonuses.length?["Random enchantment from Classic DBC reference."]:[]),
   known?"Name and rarity from the OctoWoW catalogue snapshot.":"Item details not found in the available catalogue."
 ].join("\n");
}
const baseCache=new Map();
let referencePromise;
async function referenceFor(id){
 if(!referencePromise)referencePromise=fetch("../sim/data/items/reference-tooltips.json",{cache:"force-cache"})
  .then(r=>r.ok?r.json():null).catch(()=>null);
 const ref=await referencePromise;
 return ref?.items?.[id]||null;
}
async function officialFor(id){
 try{
  const response=await fetch("https://octowow.st/db/?item="+id,{credentials:"omit",signal:AbortSignal.timeout(7000)});
  if(!response.ok)return null;
  const doc=new DOMParser().parseFromString(await response.text(),"text/html");
  const source=doc.getElementById("tooltip"+id+"-generic");
  if(!source)return null;
  const copy=source.cloneNode(true);
  for(const br of copy.querySelectorAll("br"))br.replaceWith(doc.createTextNode("\n"));
  for(const elem of copy.querySelectorAll("table,div"))elem.prepend(doc.createTextNode("\n"));
  for(const td of copy.querySelectorAll("td,th"))td.append(doc.createTextNode("\n"));
  return {tooltipText:copy.textContent.replace(/\r/g,"").replace(/[ \t]+/g," ").replace(/\n\s*\n/g,"\n").trim(),source:"OctoWoW DB"};
 }catch{return null;}
}
/** The Gear Planner-style hover includes the verified variant plus any available base tooltip. */
export async function richItemTooltip(item){
 const id=Number(item?.item_id),v=variantDetails(item),title=displayItemName(item);
 let base=null;
 if(Number.isSafeInteger(id)&&id>0){
  if(!baseCache.has(id))baseCache.set(id,(async()=>await officialFor(id)||await referenceFor(id))());
  base=await baseCache.get(id);
 }
 const raw=clean(base?.tooltipText);
 const lines=raw?raw.split("\n").map(x=>x.trim()).filter(Boolean).filter((x,i)=>i!==0||x!==clean(item?.item_name)):[];
 const details=variantLines(item);
 if(item?.item_level!=null&&!raw)lines.push("Item level "+item.item_level);
 if(item?.req_level!=null&&!raw)lines.push("Requires level "+item.req_level);
 if(details.length)lines.push("Random enchantment",...details);
 if(v.hasVariant&&v.bonuses.length)lines.push("Standard Classic DBC reference; custom values may differ.");
 if(!lines.length)lines.push("Full item attributes are not available in the catalogue.");
 if(base?.source==="OctoWoW DB")lines.push("Base stats: OctoWoW DB.");
 else if(raw)lines.push("Base stats: Gear Planner reference.");
 return {title,lines};
}
